<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#171224"><title>Sorteio | Telão</title>
<style>
*{box-sizing:border-box}html,body{width:100%;height:100%;margin:0;overflow:hidden}body{display:flex;flex-direction:column;justify-content:center;align-items:center;padding:clamp(18px,5vw,70px);background:radial-gradient(ellipse at 50% 25%,#33234a,#171224 68%);color:#fff;font-family:Arial,sans-serif}.brand{position:absolute;top:clamp(18px,4vh,38px);left:clamp(18px,4vw,56px);color:#fff;font-size:clamp(13px,2vw,21px);font-weight:800;letter-spacing:.08em}.brand span{display:block;margin-top:4px;color:#18b8b3;font-size:.62em;letter-spacing:.24em}.eyebrow{color:#b99ad9;font-size:clamp(10px,1.4vw,16px);font-weight:700;letter-spacing:.24em;text-align:center}h1{margin:14px 0 0;font-size:clamp(30px,6vw,72px);text-align:center}.crate-window{position:relative;display:flex;width:100%;height:clamp(150px,30vh,310px);margin:clamp(35px,8vh,90px) 0 24px;align-items:center;overflow:hidden;border:8px solid #422c5d;border-radius:18px;background:linear-gradient(180deg,#21182f,#50336a 50%,#21182f);box-shadow:inset 0 0 38px #09060f,0 18px 60px #0008}.crate-window:before,.crate-window:after{position:absolute;z-index:2;top:0;bottom:0;width:8%;content:'';pointer-events:none}.crate-window:before{left:0;background:linear-gradient(90deg,#21182f,transparent)}.crate-window:after{right:0;background:linear-gradient(270deg,#21182f,transparent)}.crate-track{display:flex;width:max-content;height:100%;flex:0 0 auto;align-items:center;gap:clamp(8px,1.3vw,18px);padding:0 clamp(12px,2vw,25px);will-change:transform}.crate-cell{display:grid;width:clamp(85px,10vw,155px);height:clamp(95px,19vh,205px);flex:none;place-items:center;overflow:hidden;white-space:nowrap;border:3px solid #a98ad4;border-radius:14px;background:linear-gradient(145deg,#f6f0ff,#d4c1f1);box-shadow:inset 0 0 0 5px #fff8;color:#30213f;font-size:clamp(20px,3.3vw,44px);font-variant-numeric:tabular-nums;font-weight:800;letter-spacing:-.04em}.crate-cell.is-winner{border-color:#d8ff89;background:linear-gradient(145deg,#e9ffb8,#c7f36b);box-shadow:0 0 36px #c7f36bc9,inset 0 0 0 5px #fff9;color:#24123e}.crate-marker{position:absolute;z-index:3;top:0;bottom:0;left:50%;width:5px;transform:translateX(-50%);background:#c7f36b;box-shadow:0 0 22px #c7f36b}.result{color:#c9c1d3;font-size:clamp(12px,1.8vw,20px);font-weight:700;letter-spacing:.22em;text-align:center}.result strong{display:block;margin-top:8px;color:#fff;font-size:clamp(48px,10vw,120px);letter-spacing:.04em}.hint{position:absolute;bottom:clamp(18px,4vh,38px);color:#91889d;font-size:clamp(10px,1.2vw,14px);text-align:center}.idle .crate-window{opacity:.72}@media(max-width:600px){body{padding:16px}.crate-window{height:170px;border-width:5px;margin:38px 0 20px}.crate-cell{width:clamp(70px,18vw,104px);height:105px;font-size:clamp(17px,4.2vw,24px);letter-spacing:-.05em}.crate-track{gap:7px;padding:0 10px}.brand{top:18px;left:18px}}
</style><style>
.crate-cell.is-winner{animation:winner-pop .55s cubic-bezier(.2,1.5,.4,1) both}.confetti-layer{position:absolute;z-index:4;inset:0;overflow:hidden;pointer-events:none}.confetti-piece{position:absolute;left:var(--x);top:var(--y);width:9px;height:14px;border-radius:2px;background:var(--color);opacity:0;animation:confetti-burst 1.35s cubic-bezier(.12,.65,.3,1) var(--delay) forwards}@keyframes winner-pop{0%{transform:scale(.82)}65%{transform:scale(1.09)}100%{transform:scale(1)}}@keyframes confetti-burst{0%{opacity:1;transform:translate(0,0) rotate(0) scale(1)}100%{opacity:0;transform:translate(var(--dx),var(--dy)) rotate(var(--spin)) scale(.65)}}@media(prefers-reduced-motion:reduce){.crate-cell.is-winner{animation:none}.confetti-piece{animation-duration:.01ms}}
</style></head><body class="idle"><div class="brand">SIEMENS ENERGY<span>SORTEIO</span></div><div class="eyebrow">MODO CS • SORTEIO</div><h1 id="title">Pronto para sortear</h1><div class="crate-window"><div class="crate-marker"></div><div class="crate-track" id="track"></div></div><div class="result" id="result">AGUARDANDO SORTEIO<strong>—</strong></div><div class="hint">Aguardando o colaborador iniciar o sorteio no painel</div>
<script>
const channel=new BroadcastChannel('sorteio-cs-display');
function burstConfetti(target,viewport){const old=viewport.querySelector('.confetti-layer');if(old)old.remove();const layer=document.createElement('div');layer.className='confetti-layer';viewport.appendChild(layer);const targetBox=target.getBoundingClientRect(),viewBox=viewport.getBoundingClientRect(),x=targetBox.left-viewBox.left+targetBox.width/2,y=targetBox.top-viewBox.top+targetBox.height/2,colors=['#c7f36b','#009999','#ffffff','#d8c7ff','#f4c95d'];for(let i=0;i<34;i++){const piece=document.createElement('i'),angle=(Math.PI*2*i/34)+Math.random()*.25,distance=75+Math.random()*150;piece.className='confetti-piece';piece.style.setProperty('--x',x+'px');piece.style.setProperty('--y',y+'px');piece.style.setProperty('--dx',Math.cos(angle)*distance+'px');piece.style.setProperty('--dy',Math.sin(angle)*distance+'px');piece.style.setProperty('--spin',(240+Math.random()*720)+'deg');piece.style.setProperty('--delay',(Math.random()*.12)+'s');piece.style.setProperty('--color',colors[i%colors.length]);layer.appendChild(piece)}setTimeout(()=>layer.remove(),1800)}
function animate(winner,entries){const track=document.getElementById('track'),viewport=track.parentElement,targetIndex=36,count=48,others=entries.map(e=>Number(e.numero)).filter(n=>n!==winner);document.body.classList.remove('idle');document.getElementById('title').textContent='Boa sorte!';document.getElementById('result').innerHTML='SORTEANDO<strong>—</strong>';track.style.transition='none';track.style.transform='translateX(0)';track.innerHTML='';let target;for(let i=0;i<count;i++){const cell=document.createElement('div'),number=i===targetIndex||!others.length?winner:others[Math.floor(Math.random()*others.length)];cell.className='crate-cell';cell.textContent=String(number).padStart(2,'0');if(i===targetIndex)target=cell;track.appendChild(cell)}const rect=target.getBoundingClientRect(),box=viewport.getBoundingClientRect(),offset=rect.left-box.left+rect.width/2-viewport.clientWidth/2;track.offsetHeight;requestAnimationFrame(()=>requestAnimationFrame(()=>{track.style.transition='transform 6s cubic-bezier(.08,.78,.08,1)';track.style.transform=`translateX(-${offset}px)`;setTimeout(()=>{target.classList.add('is-winner');burstConfetti(target,viewport);document.getElementById('title').textContent='Número sorteado';document.getElementById('result').innerHTML='VENCEDOR<strong>'+String(winner).padStart(2,'0')+'</strong>'},6200)}))}
channel.onmessage=event=>{const data=event.data||{};if(data.type==='draw'&&Number.isInteger(data.winner)&&Array.isArray(data.entries))animate(data.winner,data.entries)};
</script></body></html>
